/**
 * DejaVu Sans, cut down to the characters an offer letter needs, and carried
 * here as base64 rather than as files on disk.
 *
 * WHY A FONT AT ALL: the built in PDF fonts can only encode WinAnsi, which
 * has no naira sign. A salary written as "\u20a690,000" stopped the letter with
 * "WinAnsi cannot encode". The same would happen to a name written properly
 * in Yoruba, such as \u1e62\u1eb9un or \u1ecclorun\u1e63\u1ecdla, and dropping the marks from
 * someone's name on their own offer letter is not an acceptable fix.
 *
 * WHY BASE64 AND NOT A .ttf FILE: a serverless build only bundles files it
 * can see being imported. A font read from disk at run time is the kind of
 * thing that works locally and is missing in production. Imported like this
 * it is always there.
 *
 * Subset to Latin, Latin Extended A and B, Latin Extended Additional (which
 * is where the Yoruba letters live), punctuation and the currency block:
 * 741 KB down to 62 KB. Regenerate with pyftsubset if more coverage is
 * needed, for example a different script.
 */

export const DEJAVU_REGULAR =
  "";

export const DEJAVU_BOLD =
  "";

export const DEJAVU_OBLIQUE =
  "";

